{"content": "/**
 * Performance monitoring utility
 * Measures translation performance and validates against NFR-P1 targets
 */

import type { PerformanceMetrics } from '../types.js';

/**
 * Performance thresholds for different request sizes
 * NFR-P1: <10ms for 95th percentile of requests up to 100KB
 * These are component-level targets (translation overhead only)
 */
const PERFORMANCE_THRESHOLDS = {
  SMALL: {
    sizeKb: 1,
    targetMs: 2,
    description: 'Small request (~1KB, ~10 fields)'
  },
  MEDIUM: {
    sizeKb: 10,
    targetMs: 5,
    description: 'Medium request (~10KB, ~50 fields)'
  },
  LARGE: {
    sizeKb: 100,
    targetMs: 10,
    description: 'Large request (~100KB, ~100 fields)'
  }
};

/**
 * Start high-resolution performance measurement
 * Uses nanosecond-precision timing
 */
export function startPerformanceTimer(): bigint {
  return process.hrtime.bigint();
}

/**
 * End high-resolution performance measurement and calculate duration
 * @param startTimeNs Start time from startPerformanceTimer()
 * @returns PerformanceMetrics with duration in ms and ns
 */
export function endPerformanceTimer(startTimeNs: bigint): PerformanceMetrics {
  const endTimeNs = process.hrtime.bigint();
  const durationNs = endTimeNs - startTimeNs;
  const durationMs = Number(durationNs) / 1_000_000;

  return {
    duration_ms: durationMs,
    durationNs,
    startTime: startTimeNs,
    endTime: endTimeNs
  };
}

/**
 * Validate performance against thresholds
 * @param durationMs Duration in milliseconds
 * @param payloadSize Size of payload in bytes
 * @returns Validation result with indicator if under threshold
 */
export function validatePerformance(
  durationMs: number,
  payloadSize: number
): {
  isValid: boolean;
  threshold_ms: number;
  actual_ms: number;
  payloadSize: number;
  category: string;
} {
  // Determine category based on payload size
  let category = 'small';
  let thresholdMs = PERFORMANCE_THRESHOLDS.SMALL.targetMs;

  const sizeKb = payloadSize / 1024;

  if (sizeKb > PERFORMANCE_THRESHOLDS.MEDIUM.sizeKb) {
    if (sizeKb > PERFORMANCE_THRESHOLDS.LARGE.sizeKb) {
      category = 'large';
      thresholdMs = PERFORMANCE_THRESHOLDS.LARGE.targetMs;
    } else {
      category = 'medium';
      thresholdMs = PERFORMANCE_THRESHOLDS.MEDIUM.targetMs;
    }
  }

  return {
    isValid: durationMs <= thresholdMs,
    threshold_ms: thresholdMs,
    actual_ms: durationMs,
    payloadSize,
    category
  };
}

/**
 * Get performance threshold description for a payload size
 * @param payloadSize Size in bytes
 * @returns Description of threshold and target
 */
export function getPerformanceThresholdDescription(payloadSize: number): string {
  const sizeKb = payloadSize / 1024;

  if (sizeKb <= PERFORMANCE_THRESHOLDS.SMALL.sizeKb) {
    return PERFORMANCE_THRESHOLDS.SMALL.description;
  } else if (sizeKb <= PERFORMANCE_THRESHOLDS.MEDIUM.sizeKb) {
    return PERFORMANCE_THRESHOLDS.MEDIUM.description;
  } else {
    return PERFORMANCE_THRESHOLDS.LARGE.description;
  }
}

/**
 * Calculate percentile from array of durations
 * Useful for tracking 95th percentile performance
 * @param durations Array of durations in milliseconds
 * @param percentile Percentile to calculate (0-100)
 * @returns Duration at the percentile
 */
export function calculatePercentile(durations: number[], percentile: number): number {
  if (durations.length === 0) {
    return 0;
  }

  const sorted = [...durations].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return sorted[Math.max(0, index)];
}

/**
 * Calculate average duration from array
 * @param durations Array of durations in milliseconds
 * @returns Average duration
 */
export function calculateAverageDuration(durations: number[]): number {
  if (durations.length === 0) {
    return 0;
  }

  const sum = durations.reduce((acc, val) => acc + val, 0);
  return sum / durations.length;
}

/**
 * Get all performance thresholds
 */
export function getPerformanceThresholds() {
  return PERFORMANCE_THRESHOLDS;
}
